cd /home/admin/backend && php artisan tinker --execute="
use Illuminate\Support\Facades\DB;
use App\Services\ScheduleGuardService;

// Check the guard service with a mock scenario:
// If a course has a 'rescheduled' entry on the same date,
// verify that the scheduled rows for that course are excluded.

\$guard = app(ScheduleGuardService::class);

// Use reflection to test buildTeacherDateOccupancyEntries
\$ref = new ReflectionClass(\$guard);
\$method = \$ref->getMethod('buildTeacherDateOccupancyEntries');
\$method->setAccessible(true);

// Find a teacher with actual scheduled data to test against
\$teacherId = 29;
\$branchRow = DB::table('StudentClass as sc')
    ->join('Student as st', 'st.id', '=', 'sc.StudentID')
    ->where('sc.TeacherID', \$teacherId)
    ->where('sc.Stop', 0)
    ->select('st.CampusID')
    ->first();
\$branchId = \$branchRow ? (int)\$branchRow->CampusID : 1;

// Find a date with ClassSessions for this teacher
\$sessionDate = DB::table('ClassSession as cs')
    ->join('StudentClass as sc', 'sc.ID', '=', 'cs.StudentClassID')
    ->where('sc.TeacherID', \$teacherId)
    ->where('cs.Status', 'scheduled')
    ->orderBy('cs.SessionDate', 'desc')
    ->value('cs.SessionDate');

if (\$sessionDate) {
    echo 'Testing with teacher=' . \$teacherId . ', branch=' . \$branchId . ', date=' . \$sessionDate . PHP_EOL;

    \$entries = \$method->invoke(\$guard, \$teacherId, \$branchId, \$sessionDate);
    echo 'Occupancy entries count: ' . count(\$entries) . PHP_EOL;
    foreach (\$entries as \$e) {
        echo '  source=' . \$e['source'] . ' id=' . \$e['source_id'] . ' student=' . \$e['student_id'] . ' ' . \$e['start_time'] . '-' . \$e['end_time'] . PHP_EOL;
    }
} else {
    echo 'No scheduled sessions found for teacher ' . \$teacherId . PHP_EOL;
}
echo PHP_EOL . 'Guard service is functional.' . PHP_EOL;
"
